//! Per-version protocol data: packet names in ID order, built-in registries
//! and block states. The files under `data/` are generated by
//! `scripts/translation_crate.py` (also `scripts/translation_data.py crate`);
//! `build.rs` packs them into one archive that is unpacked on first use.
//!
//! Names are stored without the `minecraft:` namespace.
use crate::{Direction, State};
use serde::Deserialize;
use serde_json::Value;
use std::{
    collections::HashMap,
    io::Read,
    sync::{Mutex, OnceLock},
};

/// Strip the default namespace: data files and lookups use bare paths.
pub fn strip(name: &str) -> &str {
    name.strip_prefix("minecraft:").unwrap_or(name)
}

/// The packed `data/` directory: file stem to parsed JSON.
fn archive() -> &'static HashMap<String, Value> {
    static ARCHIVE: OnceLock<HashMap<String, Value>> = OnceLock::new();
    ARCHIVE.get_or_init(|| {
        let packed: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/data.json.gz"));
        let mut text = String::new();
        flate2::read::GzDecoder::new(packed)
            .read_to_string(&mut text)
            .expect("embedded translation data is gzip");
        serde_json::from_str(&text).expect("embedded translation data is JSON")
    })
}

/// A raw data file by its path under `data/` without `.json`, such as
/// `"rules/393-401"`. `None` when the file does not exist.
pub fn file(stem: &str) -> Option<&'static Value> {
    archive().get(stem)
}

/// A registry's entries in network-ID order. Versions before 1.13 number
/// some registries sparsely; a gap has no name.
#[derive(Debug, Default)]
pub struct Registry {
    names: Vec<Option<Box<str>>>,
    ids: HashMap<Box<str>, i32>,
}

impl Registry {
    pub fn new(names: Vec<Option<String>>) -> Self {
        let names: Vec<Option<Box<str>>> = names
            .into_iter()
            .map(|name| name.map(String::into_boxed_str))
            .collect();
        let mut ids = HashMap::with_capacity(names.len());
        for (id, name) in names.iter().enumerate() {
            if let Some(name) = name {
                // The first ID wins should a legacy registry repeat a name.
                ids.entry(name.clone()).or_insert(id as i32);
            }
        }
        Self { names, ids }
    }

    /// One past the highest ID.
    pub fn len(&self) -> usize {
        self.names.len()
    }

    pub fn is_empty(&self) -> bool {
        self.names.is_empty()
    }

    pub fn name(&self, id: i32) -> Option<&str> {
        self.names.get(usize::try_from(id).ok()?)?.as_deref()
    }

    /// The ID of `name`, with or without the `minecraft:` namespace.
    pub fn id(&self, name: &str) -> Option<i32> {
        self.ids.get(strip(name)).copied()
    }

    pub fn names(&self) -> impl Iterator<Item = (i32, &str)> {
        self.names
            .iter()
            .enumerate()
            .filter_map(|(id, name)| Some((id as i32, name.as_deref()?)))
    }
}

/// One block and its states. State IDs are consecutive from `first_state`,
/// enumerating the properties as a cartesian product with the last property
/// varying fastest, which is how the game numbers them.
#[derive(Debug)]
pub struct Block {
    pub name: Box<str>,
    /// Property names with their values, in the game's order.
    pub properties: Vec<(Box<str>, Vec<Box<str>>)>,
    pub first_state: i32,
    /// Offset of the default state from `first_state`.
    pub default_offset: i32,
}

impl Block {
    pub fn state_count(&self) -> i32 {
        self.properties
            .iter()
            .map(|(_, values)| values.len() as i32)
            .product()
    }

    pub fn default_state(&self) -> i32 {
        self.first_state + self.default_offset
    }

    /// The value of every property for the state at `offset`.
    pub fn values(&self, offset: i32) -> Vec<(&str, &str)> {
        let mut remaining = offset;
        let mut result = vec![("", ""); self.properties.len()];
        for (index, (name, values)) in self.properties.iter().enumerate().rev() {
            let count = values.len() as i32;
            result[index] = (&**name, &*values[(remaining % count) as usize]);
            remaining /= count;
        }
        result
    }

    /// The offset of the state with these property values; properties not
    /// named keep the default state's value.
    pub fn offset(&self, wanted: &[(&str, &str)]) -> Option<i32> {
        let defaults = self.values(self.default_offset);
        let mut offset = 0;
        for (index, (name, values)) in self.properties.iter().enumerate() {
            let value = wanted
                .iter()
                .find(|(wanted, _)| *wanted == &**name)
                .map_or(defaults[index].1, |(_, value)| *value);
            let position = values.iter().position(|known| &**known == value)?;
            offset = offset * values.len() as i32 + position as i32;
        }
        Some(offset)
    }
}

/// A block as stored: name, properties with their values, default offset.
type RawBlock = (String, Vec<(String, Vec<String>)>, i32);

/// The flattened (1.13+) block states of one version.
#[derive(Debug, Default)]
pub struct BlockStates {
    pub blocks: Vec<Block>,
    by_name: HashMap<Box<str>, usize>,
    total: i32,
}

impl BlockStates {
    fn new(raw: Vec<RawBlock>) -> Self {
        let mut blocks = Vec::with_capacity(raw.len());
        let mut by_name = HashMap::with_capacity(raw.len());
        let mut next = 0;
        for (name, properties, default_offset) in raw {
            let block = Block {
                name: name.into_boxed_str(),
                properties: properties
                    .into_iter()
                    .map(|(name, values)| {
                        (
                            name.into_boxed_str(),
                            values.into_iter().map(String::into_boxed_str).collect(),
                        )
                    })
                    .collect(),
                first_state: next,
                default_offset,
            };
            next += block.state_count();
            by_name.insert(block.name.clone(), blocks.len());
            blocks.push(block);
        }
        Self {
            blocks,
            by_name,
            total: next,
        }
    }

    /// The number of block states.
    pub fn len(&self) -> i32 {
        self.total
    }

    pub fn is_empty(&self) -> bool {
        self.total == 0
    }

    pub fn block(&self, name: &str) -> Option<&Block> {
        self.by_name
            .get(strip(name))
            .map(|index| &self.blocks[*index])
    }

    /// The block owning state `id` and the state's offset within it.
    pub fn locate(&self, id: i32) -> Option<(&Block, i32)> {
        if id < 0 || id >= self.total {
            return None;
        }
        let index = self.blocks.partition_point(|block| block.first_state <= id) - 1;
        let block = &self.blocks[index];
        Some((block, id - block.first_state))
    }

    /// `name[property=value,...]`, the form rules and tests use.
    pub fn describe(&self, id: i32) -> Option<String> {
        let (block, offset) = self.locate(id)?;
        let values = block.values(offset);
        if values.is_empty() {
            return Some(block.name.to_string());
        }
        let properties: Vec<String> = values
            .iter()
            .map(|(name, value)| format!("{name}={value}"))
            .collect();
        Some(format!("{}[{}]", block.name, properties.join(",")))
    }

    /// Parse `name` or `name[property=value,...]` into a state ID.
    pub fn parse(&self, state: &str) -> Option<i32> {
        let (name, properties) = match state.split_once('[') {
            Some((name, rest)) => (name, rest.strip_suffix(']')?),
            None => (state, ""),
        };
        let block = self.block(name)?;
        let wanted: Vec<(&str, &str)> = properties
            .split(',')
            .filter(|pair| !pair.is_empty())
            .map(|pair| pair.split_once('='))
            .collect::<Option<_>>()?;
        Some(block.first_state + block.offset(&wanted)?)
    }
}

#[derive(Deserialize)]
struct RawVersion {
    protocol: i32,
    name: String,
    #[serde(default)]
    packets: HashMap<String, Vec<String>>,
    #[serde(default)]
    registries: HashMap<String, Vec<Option<String>>>,
    #[serde(default)]
    blocks: Vec<RawBlock>,
    #[serde(flatten)]
    extra: HashMap<String, Value>,
}

/// Packet names of one state and direction, in packet-ID order.
#[derive(Debug, Default)]
pub struct PacketTable {
    names: Vec<Box<str>>,
    ids: HashMap<Box<str>, i32>,
}

impl PacketTable {
    pub fn names(&self) -> &[Box<str>] {
        &self.names
    }

    pub fn name(&self, id: i32) -> Option<&str> {
        self.names
            .get(usize::try_from(id).ok()?)
            .map(|name| &**name)
    }

    pub fn id(&self, name: &str) -> Option<i32> {
        self.ids.get(name).copied()
    }
}

/// Everything known about one protocol version.
#[derive(Debug)]
pub struct VersionData {
    pub protocol: i32,
    /// The newest release with this protocol.
    pub name: String,
    packets: HashMap<(State, Direction), PacketTable>,
    registries: HashMap<String, Registry>,
    pub block_states: BlockStates,
    /// Version-specific sections outside the common schema.
    pub extra: HashMap<String, Value>,
}

static EMPTY_PACKETS: OnceLock<PacketTable> = OnceLock::new();

impl VersionData {
    fn load(raw: RawVersion) -> Self {
        let mut packets = HashMap::new();
        for (key, names) in raw.packets {
            let (state, direction) = key
                .split_once('/')
                .unwrap_or_else(|| panic!("invalid packet table key {key}"));
            let state = match state {
                "handshake" => State::Handshake,
                "status" => State::Status,
                "login" => State::Login,
                "configuration" => State::Configuration,
                "play" => State::Play,
                _ => panic!("invalid packet table key {key}"),
            };
            let direction = match direction {
                "clientbound" => Direction::Clientbound,
                "serverbound" => Direction::Serverbound,
                _ => panic!("invalid packet table key {key}"),
            };
            let names: Vec<Box<str>> = names.into_iter().map(String::into_boxed_str).collect();
            let ids = names
                .iter()
                .enumerate()
                .map(|(id, name)| (name.clone(), id as i32))
                .collect();
            packets.insert((state, direction), PacketTable { names, ids });
        }
        Self {
            protocol: raw.protocol,
            name: raw.name,
            packets,
            registries: raw
                .registries
                .into_iter()
                .map(|(name, names)| (name, Registry::new(names)))
                .collect(),
            block_states: BlockStates::new(raw.blocks),
            extra: raw.extra,
        }
    }

    /// The packets of `state` in `direction`; empty when the version has none.
    pub fn packets(&self, state: State, direction: Direction) -> &PacketTable {
        self.packets
            .get(&(state, direction))
            .unwrap_or_else(|| EMPTY_PACKETS.get_or_init(PacketTable::default))
    }

    pub fn packet_name(&self, state: State, direction: Direction, id: i32) -> Option<&str> {
        self.packets(state, direction).name(id)
    }

    pub fn packet_id(&self, state: State, direction: Direction, name: &str) -> Option<i32> {
        self.packets(state, direction).id(name)
    }

    /// The ID of a packet that must exist, for step constructors.
    pub fn expect_packet(&self, state: State, direction: Direction, name: &str) -> i32 {
        self.packet_id(state, direction, name).unwrap_or_else(|| {
            panic!(
                "{} has no {state:?} {direction:?} packet named {name}",
                self.name
            )
        })
    }

    /// A built-in registry such as `"item"` or `"entity_type"`.
    pub fn registry(&self, name: &str) -> Option<&Registry> {
        self.registries.get(strip(name))
    }

    /// A registry that must exist, for step constructors.
    pub fn expect_registry(&self, name: &str) -> &Registry {
        self.registry(name)
            .unwrap_or_else(|| panic!("{} has no {name} registry", self.name))
    }

    pub fn registry_names(&self) -> impl Iterator<Item = &str> {
        self.registries.keys().map(String::as_str)
    }
}

/// The data of `protocol`, or `None` when it has no data file.
pub fn try_version(protocol: i32) -> Option<&'static VersionData> {
    static VERSIONS: OnceLock<Mutex<HashMap<i32, Option<&'static VersionData>>>> = OnceLock::new();
    let mut versions = VERSIONS.get_or_init(Default::default).lock().unwrap();
    *versions.entry(protocol).or_insert_with(|| {
        let raw = file(&protocol.to_string())?;
        let raw: RawVersion = RawVersion::deserialize(raw)
            .unwrap_or_else(|error| panic!("invalid data for protocol {protocol}: {error}"));
        assert_eq!(raw.protocol, protocol, "data file names its protocol");
        Some(Box::leak(Box::new(VersionData::load(raw))))
    })
}

/// The data of a protocol listed in [`crate::version::PROTOCOLS`].
pub fn version(protocol: i32) -> &'static VersionData {
    try_version(protocol).unwrap_or_else(|| panic!("no translation data for protocol {protocol}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn states() -> BlockStates {
        BlockStates::new(vec![
            ("air".into(), vec![], 0),
            (
                "lever".into(),
                vec![
                    ("face".into(), vec!["floor".into(), "wall".into()]),
                    ("powered".into(), vec!["true".into(), "false".into()]),
                ],
                1,
            ),
            ("stone".into(), vec![], 0),
        ])
    }

    #[test]
    fn block_states_enumerate_with_the_last_property_fastest() {
        let states = states();
        assert_eq!(states.len(), 6);
        assert_eq!(states.describe(0).unwrap(), "air");
        assert_eq!(
            states.describe(1).unwrap(),
            "lever[face=floor,powered=true]"
        );
        assert_eq!(
            states.describe(2).unwrap(),
            "lever[face=floor,powered=false]"
        );
        assert_eq!(
            states.describe(4).unwrap(),
            "lever[face=wall,powered=false]"
        );
        assert_eq!(states.describe(5).unwrap(), "stone");
        assert_eq!(states.describe(6), None);
        assert_eq!(states.block("minecraft:lever").unwrap().default_state(), 2);
        for id in 0..states.len() {
            assert_eq!(states.parse(&states.describe(id).unwrap()), Some(id));
        }
        // Unnamed properties keep the default state's value.
        assert_eq!(states.parse("lever[face=wall]"), Some(4));
        assert_eq!(states.parse("lever[face=ceiling]"), None);
        assert_eq!(states.parse("dirt"), None);
    }

    #[test]
    fn every_protocol_has_its_essentials() {
        use crate::version::{PROTOCOLS, has_configuration};
        use Direction::*;
        for &(protocol, name) in PROTOCOLS {
            let data = version(protocol);
            assert_eq!((data.protocol, data.name.as_str()), (protocol, name));
            for direction in [Clientbound, Serverbound] {
                assert!(
                    !data.packets(State::Play, direction).names().is_empty(),
                    "{name} has no play {direction:?} packets"
                );
            }
            // The names the translator follows the protocol phase by.
            let mut required = vec![
                (State::Handshake, Serverbound, "intention"),
                (State::Login, Clientbound, "login_finished"),
                (State::Login, Clientbound, "login_compression"),
                (State::Play, Clientbound, "keep_alive"),
                (State::Play, Serverbound, "keep_alive"),
                (State::Play, Clientbound, "custom_payload"),
                (State::Play, Serverbound, "custom_payload"),
                (State::Play, Clientbound, "login"),
                (State::Play, Clientbound, "disconnect"),
            ];
            if has_configuration(protocol) {
                required.extend([
                    (State::Login, Serverbound, "login_acknowledged"),
                    (State::Configuration, Clientbound, "finish_configuration"),
                    (State::Configuration, Serverbound, "finish_configuration"),
                    (State::Play, Clientbound, "start_configuration"),
                    (State::Play, Serverbound, "configuration_acknowledged"),
                ]);
            } else {
                assert!(
                    data.packets(State::Configuration, Clientbound)
                        .names()
                        .is_empty()
                );
            }
            for (state, direction, packet) in required {
                data.expect_packet(state, direction, packet);
            }
        }
    }

    #[test]
    fn registries_resolve_names_with_and_without_namespace() {
        let registry = Registry::new(vec![Some("air".into()), None, Some("stone".into())]);
        assert_eq!(registry.len(), 3);
        assert_eq!(registry.id("minecraft:stone"), Some(2));
        assert_eq!(registry.id("stone"), Some(2));
        assert_eq!(registry.name(1), None);
        assert_eq!(registry.name(-1), None);
        assert_eq!(registry.names().count(), 2);
    }
}
